180		}
181		if got.State != RequestReserved || got.ApproverAccountID != "payer" {
182			t.Fatalf("approve view = %+v, want reserved by payer", got)
183		}
184	
185		// 吊销提交申请所用的会话：只改变会话状态，不动已预留费用。
186		if err := w.RevokeSession("s1"); err != nil {
187			t.Fatal(err)
188		}
189		checkSessionsAfterRace(t, w)
190		checkApproveWonOutcome(t, w, createdAt, waitDeadline, approveAt)
