func TestConcurrentRevokeApproverSessionAndApprove(t *testing.T) {
	const iterations = 32
	outcomes := map[string]int{}
	for i := 0; i < iterations; i++ {
		w, c := setupApproval(t)
		createdAt, waitDeadline := applyPendingForRace(t, w)
		c.t = c.t.Add(10 * time.Second)
