			t.Fatalf("repeat approve rewrote first decision: decided %v reserved %v, want %v",
				again.DecidedAt, again.ReservedAt, approveAt)
		}
		checkApproveWonOutcome(t, w, createdAt, waitDeadline, approveAt)
	})
}

